def schema(path,title,service=False):
 business={'@type':'DaySpa','@id':OFFICIAL+'/#business','name':'Wellness Origin Spa','url':OFFICIAL+'/','telephone':'+1-317-979-1234','email':'support@wellnessorigin.com','address':{'@type':'PostalAddress','streetAddress':'937 Keystone Way N.','addressLocality':'Carmel','addressRegion':'IN','postalCode':'46032','addressCountry':'US'},'logo':ORIGIN+'/assets/logo.png','openingHoursSpecification':[{'@type':'OpeningHoursSpecification','dayOfWeek':['Monday','Tuesday','Wednesday','Thursday','Friday'],'opens':'10:00','closes':'19:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Saturday','opens':'10:00','closes':'17:00'}]}
 graph=[business,{'@type':'WebSite','@id':ORIGIN+'/#website','url':ORIGIN+'/','name':'Wellness Origin Spa','publisher':{'@id':OFFICIAL+'/#business'}},{'@type':'WebPage','@id':ORIGIN+path+'#webpage','url':ORIGIN+path,'name':title,'isPartOf':{'@id':ORIGIN+'/#website'},'about':{'@id':OFFICIAL+'/#business'}}]
 if path!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title,'item':ORIGIN+path}]})
 if service:graph.append({'@type':'Service','@id':ORIGIN+path+'#service','name':services[path][0],'serviceType':services[path][0],'url':ORIGIN+path,'provider':{'@id':OFFICIAL+'/#business'},'areaServed':{'@type':'City','name':'Carmel, Indiana'}})
 return json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')
def render(path,title,description,body,imgname='hero',service=False):
 robots='index,follow,max-image-preview:large' if INDEXABLE and path not in ['/preview-notes/','/author/ericadmin/'] else 'noindex,follow'
 canonical=ORIGIN+path; metaimg=ORIGIN+f'/assets/{imgname}-'+('1200' if imgname=='hero' else '960')+'.webp'
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="{robots}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#493952"><meta property="og:type" content="website"><meta property="og:site_name" content="Wellness Origin Spa"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{metaimg}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{metaimg}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css?v=2"><script src="/app.js" defer></script><script type="application/ld+json">{schema(path,title,service)}</script></head><body id="top">{header(path)}<main id="main">{body}</main>{footer()}</body></html>'''
 out=out.replace('↗','<svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" style="display:inline-block;vertical-align:middle;flex-shrink:0"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" stroke-width="1.4"/></svg>').replace('✳','<svg aria-hidden="true" width="36" height="36" viewBox="0 0 40 40" fill="none"><g stroke="currentColor"><ellipse cx="20" cy="20" rx="6" ry="17"/><ellipse cx="20" cy="20" rx="6" ry="17" transform="rotate(60 20 20)"/><ellipse cx="20" cy="20" rx="6" ry="17" transform="rotate(120 20 20)"/></g></svg>')
 dest=DIST/path.strip('/')/'index.html' if path!='/' else DIST/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)
def crumbs(path,name):return f'<div class="shell breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>'+('<a href="/spa-services/">Treatments</a><span aria-hidden="true">/</span>' if path in services else '')+f'<span>{e(name)}</span></div>'
